var DX_BODY = window.DX_BODY || {};

/* ==================== إنذارات الدماغ الحادّة ==================== */

DX_BODY['tia'] = {
  symptoms: {
    ar: 'تبدأ فجأة وبلا مقدّمات، وتكون في ذروتها من أول لحظة: خدر أو ضعف في نصف الوجه أو في ذراع أو ساق من جهة واحدة، أو تلعثم في الكلام أو عجز عن إيجاد الكلمة، أو كلام مفهوم عند صاحبه غير مفهوم لمن حوله. وقد تكون العلامة بصرية بحتة: ستارة سوداء تنزل على عين واحدة لدقائق ثم ترتفع، أو ازدواج في الرؤية. وقد تكون دوخة شديدة مع اختلال في التوازن وعدم اتزان في اليد. وما يميّز النوبة العابرة أن كل هذا يزول من نفسه خلال دقائق إلى ساعة، فيرتاح صاحبه ويقول انتهى الأمر، ويعود إلى يومه. وهذا الارتياح بالذات هو الخطر: العرَض زال والسبب لم يزل، والشريان الذي أطلق الجلطة الصغيرة ما زال قادراً على إطلاق ما هو أكبر.',
    en: 'It begins suddenly with no warning and is at its peak from the first moment: numbness or weakness in one half of the face, or in an arm or leg on one side; slurred speech or an inability to find the word; or speech that makes sense to its owner but not to those around him. The sign may be purely visual: a black curtain descending over one eye for minutes then lifting, or double vision. It may be severe dizziness with unsteadiness. What marks a transient attack is that all this clears by itself within minutes to an hour, so the person is relieved and says it is over. That very relief is the danger: the symptom has gone but the cause has not, and the artery that threw the small clot can still throw a larger one.'
  },
  cause: {
    ar: 'السبب هو انقطاع قصير للدم عن جزء من الدماغ ثم عودته قبل أن تموت الخلايا. ومصدر الانسداد غالباً جلطة صغيرة انفصلت عن لويحة عصيدية في شريان الرقبة السباتي أو في الأبهر، أو خثرة تكوّنت داخل القلب حين يكون نظمه مضطرباً كالرجفان الأذيني فتسافر مع الدم حتى تعلق في شريان دماغي دقيق، ثم تتفتّت وتمرّ فيعود التروية. وقد يكون السبب تضيّقاً شديداً في شريان صغير داخل الدماغ. وعوامل الخطر هي نفسها عوامل السكتة والجلطة القلبية: ارتفاع ضغط الدم وهو الأقوى، والسكري، وارتفاع الكوليسترول، والتدخين، واضطراب نظم القلب، والسمنة وقلّة الحركة، والتاريخ العائلي والسنّ. ومن أصيب بنوبة عابرة فقد أُعلن أن هذه الشبكة كلها في خطر.',
    en: 'The cause is a brief interruption of blood to part of the brain that is restored before the cells die. The blockage usually comes from a small clot broken off an atherosclerotic plaque in the carotid artery of the neck or in the aorta, or from a clot formed inside the heart when its rhythm is disturbed, as in atrial fibrillation, which travels until it lodges in a fine brain artery, then breaks up and passes so perfusion returns. It may also be severe narrowing of a small artery within the brain. The risk factors are those of stroke and heart attack: high blood pressure above all, diabetes, high cholesterol, smoking, irregular heart rhythm, obesity and inactivity, family history and age.'
  },
  diagnosis: {
    ar: 'التقييم يجب أن يتمّ في اليوم نفسه لا في موعد بعد أسبوع، لأن أعلى خطر للسكتة يقع في الساعات الثمانٍ والأربعين الأولى. يبدأ الطبيب بفحص عصبي دقيق وقياس الضغط والسكر، ثم تصوير للدماغ بالمقطعية أو بالرنين المغناطيسي، والرنين أدقّ لأنه قد يُظهر بقعة إقفار صغيرة حقيقية فتصير الحالة سكتة صغيرة لا نوبة عابرة. ثم يُصوَّر شريانا الرقبة بالموجات الصوتية أو بالأشعة بالصبغة بحثاً عن تضيّق يستحقّ التدخّل. ويُخطَّط القلب ويُراقَب نظمه لمدّة، لأن الرجفان الأذيني قد يكون متقطّعاً فلا يظهر في تخطيط واحد وهو سبب شائع يغيّر العلاج كلّه. وتُسحب تحاليل للدهون والسكر التراكمي والدم، ويُصوَّر القلب بالموجات إن اشتُبه بمصدر قلبي.',
    en: 'Assessment must happen the same day, not at an appointment a week later, because the highest risk of stroke falls in the first forty-eight hours. The doctor begins with a careful neurological examination and measures blood pressure and sugar, then images the brain by CT or MRI; MRI is more accurate because it may show a genuine small area of ischaemia, which turns the event into a minor stroke rather than a transient attack. The neck arteries are then imaged by ultrasound or contrast scanning to look for a narrowing worth treating. The heart is traced and its rhythm monitored for a period, since atrial fibrillation may be intermittent, missed on a single tracing, and it changes the whole treatment. Blood lipids, sugar and blood counts are drawn.'
  },
  treatment: {
    ar: 'الهدف واحد: منع السكتة التي تلي. ويبدأ العلاج عادةً في اليوم الأول لا بعد اكتمال الفحوص، لأن التأخير يكلّف. ويشمل دواءً يمنع تكدّس الصفائح الدموية يحدّده الطبيب، أو مانعاً للتخثّر من نوع آخر إن كان المصدر قلبياً كالرجفان الأذيني، ولا يخلط المريض بين الاثنين ولا يوقفهما من تلقاء نفسه. ويُضاف خافض للكوليسترول من الفئة القوية، وضبط صارم لضغط الدم والسكري. وإن وُجد تضيّق شديد في الشريان السباتي فقد يُنصح بجراحة تنظّفه أو دعامة توسّعه، وتوقيتها في الأسابيع الأولى مهمّ. ويبقى ما يعتمد على المريض وحده وأثره كبير: إقلاع تامّ عن التدخين، وحركة يومية، وطعام أقلّ ملحاً ودهناً مشبعاً، وإنقاص الوزن، وعلاج انقطاع النفس النومي إن وُجد.',
    en: 'The aim is single: preventing the stroke that follows. Treatment usually begins on the first day rather than after all tests are complete, because delay costs. It includes a medicine that stops platelets clumping, chosen by the doctor, or an anticoagulant of another kind if the source is cardiac such as atrial fibrillation; the patient must not confuse the two nor stop them alone. A strong cholesterol-lowering agent is added, with tight control of blood pressure and diabetes. If a severe narrowing of the carotid artery is found, surgery to clean it or a stent to widen it may be advised, and its timing in the first weeks matters. What depends on the patient carries great weight: stopping smoking entirely, daily movement, less salt and saturated fat, weight loss, and treating sleep apnoea.'
  },
  seeDoctor: {
    ar: 'اتصل بالإسعاف فوراً وأنت في النوبة ولا تنتظر أن تزول: تدلّي نصف الوجه، أو ضعف ذراع لا ترتفع، أو كلام متلعثم — وهذي علامات السكتة نفسها ولا أحد يعرف وقتها هل ستزول. وإن زالت الأعراض قبل أن تصل، فلا ترجع إلى البيت ولا تؤجّل الأمر لموعد: اذهب للطوارئ في اليوم نفسه، فزوال العرَض ليس زوال الخطر، وأعلى احتمال لسكتة كاملة يكون في اليومين التاليين مباشرة. ولا تقُد سيارتك بنفسك، وتوقّف عن القيادة من تلك اللحظة: القاعدة بعد النوبة العابرة أو السكتة ألّا تقود شهراً على الأقلّ، ولا ترجع للقيادة إلا حين يأذن لك طبيبك. واذهب في اليوم نفسه أيضاً إذا نزلت ستارة سوداء على عين واحدة لدقائق، أو تكرّرت نوبات قصيرة متقاربة فهذا أشدّ إنذاراً. وبعد النجاة، أي عرَض جديد يعود ولو ثوانيَ = طوارئ من جديد لا اتصال بالعيادة.',
    en: 'Call an ambulance at once while the attack is happening and do not wait for it to pass: a drooping half-face, an arm that will not lift, or slurred speech — these are the signs of stroke itself and no one knows at the time whether they will clear. If the symptoms have gone before you arrive, do not go home and do not postpone to an appointment: go to emergency the same day, because the symptom clearing is not the danger clearing, and the highest chance of a full stroke is in the two days that follow. Do not drive yourself, and stop driving from that moment: after a transient ischaemic attack or a stroke the rule is not to drive for at least one month, and to start again only when your doctor says it is safe. Go the same day too if a black curtain fell over one eye for minutes, or if short attacks repeat close together, which warns more strongly. Any new symptom afterwards, even for seconds, is an emergency again.'
  },
  updated: '2026-09-08'
};

DX_BODY['sah'] = {
  symptoms: {
    ar: 'العلامة التي لا تُنسى صداع ينفجر فجأة ويبلغ أقصاه في ثوانٍ لا في دقائق، يصفه أصحابه بأنه أسوأ صداع في حياتهم أو كأن شيئاً انفجر في الرأس أو ضربة عصا على مؤخّرة الرأس. وكثيراً ما يبدأ أثناء مجهود أو انفعال أو رفع ثقيل أو أثناء الجماع أو حتى في الحمّام. يصحبه غثيان وقيء، وتيبّس في الرقبة يظهر بعد ساعات، ونفور شديد من الضوء، وقد يفقد المريض وعيه لحظات ثم يصحو مشوّشاً، أو يبقى فاقداً للوعي. وقد تسبق النزفَ الكبيرَ بأيام أو أسابيع نوبةُ صداع شديدة مفاجئة تزول من نفسها فتُنسى، وهي تسريب صغير ينذر بما هو أكبر. وقد يظهر ازدواج رؤية أو تدلّي جفن أو ضعف في طرف.',
    en: 'The unforgettable sign is a headache that explodes suddenly and reaches its peak in seconds rather than minutes, described as the worst headache of a lifetime, as though something burst in the head or a stick struck the back of it. It often begins during exertion, emotion, lifting, intercourse or even in the bathroom. It comes with nausea and vomiting, a stiff neck appearing after hours, strong dislike of light, and the person may lose consciousness for moments then wake confused, or remain unconscious. Days or weeks before a large bleed, a sudden severe headache may come and clear by itself and be forgotten: a small warning leak. Double vision, a drooping eyelid or limb weakness may appear.'
  },
  cause: {
    ar: 'الأصل أن الدماغ يسبح في سائل داخل حيّز بين غشاءين، وفيه تمرّ الشرايين الكبيرة عند قاعدته. وحين ينتفخ جدار أحد هذه الشرايين في نقطة ضعف خلقية فيصير كبالون رفيع الجدار، ثم يتمزّق، ينسكب الدم بضغط الشريان في هذا الحيّز ويحيط بالدماغ ويرفع الضغط داخل الجمجمة في لحظات. وهذا هو السبب الأشيع، وهو ما يُسمّى تمدّد الأوعية أو أمّ الدم. وقد يكون السبب تشوّهاً في شبكة الأوعية، أو إصابة رأس. وما يزيد احتماله: ارتفاع ضغط الدم غير المضبوط، والتدخين وهو عامل قوي، والإفراط في الكحول، ووجود إصابة في الأقارب من الدرجة الأولى، وبعض الأمراض الوراثية كتكيّس الكلى. وهو يصيب أعماراً أصغر من السكتة المعتادة.',
    en: 'The brain floats in fluid within a space between two membranes, and the large arteries run through it at its base. When the wall of one of these arteries balloons at a congenital weak point into a thin-walled sac and then tears, blood pours at arterial pressure into that space, surrounds the brain and raises the pressure inside the skull within moments. This is the commonest cause, an aneurysm. Others are a malformation of the vessel network, or a head injury. What raises the risk: uncontrolled high blood pressure, smoking which weighs heavily, excess alcohol, an affected first-degree relative, and some inherited conditions such as polycystic kidney disease. It strikes younger ages than ordinary stroke.'
  },
  diagnosis: {
    ar: 'أول فحص أشعة مقطعية للرأس بلا صبغة، وهي شديدة الحساسية في الساعات الأولى وتُظهر الدم أبيض حول الدماغ، لكن حساسيتها تنقص كلّما مرّ الوقت لأن الدم يتحلّل. ولذلك إذا كانت القصّة قصّة صداع صاعقة والمقطعية سليمة، لا يُصرف المريض: يُجرى بزل قطني بعد ساعات من بدء الصداع، إذ يُسحب قليل من السائل الشوكي ويُنظر هل فيه دم أو صبغة صفراء ناتجة عن تحلّل الدم، وهي دليل النزف حتى بعد أن تصفو الأشعة. وحين يُثبت النزف يُصوَّر شريان الدماغ بالصبغة، مقطعياً أو بالقسطرة، لتحديد موضع التمدّد وشكله وعنقه، لأن ذلك هو ما يقرّر طريقة إغلاقه. وتُراقب الحالة بعدها بحثاً عن تشنّج الشرايين واستسقاء الرأس.',
    en: 'The first test is a non-contrast CT of the head, highly sensitive in the first hours and showing the blood white around the brain, though its sensitivity falls as time passes and the blood breaks down. So if the story is one of a thunderclap headache and the CT is clean, the patient is not discharged: a lumbar puncture is done some hours after the headache began, drawing a little spinal fluid to see whether it contains blood or the yellow pigment of broken-down blood, which proves a bleed even after the scan has cleared. Once proven, the brain arteries are imaged with contrast, by CT or catheter, to define the aneurysm\'s site, shape and neck, since that decides how it is closed. The patient is then watched for vessel spasm and hydrocephalus.'
  },
  treatment: {
    ar: 'حالة تُدار في العناية المركّزة في مركز فيه جراحة أعصاب وقسطرة دماغية. والخطوة الحاسمة إغلاق مصدر النزف بسرعة قبل أن يعاود، لأن معاودة النزف هي أكبر أسباب الوفاة وتقع غالباً في الأيام الأولى. ويتمّ الإغلاق بإحدى طريقتين يختار بينهما الفريق حسب موضع التمدّد وشكله: قسطرة تدخل من شريان الفخذ وتملأ الكيس بلفائف معدنية دقيقة تُخثّر الدم داخله، أو جراحة تفتح الجمجمة وتضع مشبكاً على عنق الكيس. وحول ذلك عناية دقيقة: ضبط الضغط والألم، ومنع الشدّ والإجهاد، ومراقبة تشنّج الشرايين الذي يظهر بعد أيام ويُعالج طبّياً، وتصريف السائل إن تراكم. ثم متابعة طويلة وضبط الضغط وإقلاع تامّ عن التدخين ومسح الأقارب عند وجود تاريخ عائلي.',
    en: 'This is managed in intensive care at a centre with neurosurgery and neuro-interventional catheterisation. The decisive step is closing the source of bleeding quickly before it bleeds again, since re-bleeding is the largest cause of death and usually occurs in the first days. Closure is by one of two routes chosen by the team according to the aneurysm: a catheter passed from the groin artery that fills the sac with fine metal coils so the blood inside clots, or open surgery that places a clip across its neck. Around this comes careful management: control of pressure and pain, avoiding straining, watching for the vessel spasm that appears after days and is treated medically, and draining fluid if it accumulates. Long follow-up, blood pressure control and complete cessation of smoking follow.'
  },
  seeDoctor: {
    ar: 'اطلب الإسعاف فوراً — هذي ليست حالة عيادة ولا انتظار — إذا جاءك صداع بلغ أشدّه في أقلّ من دقيقة، ولو خفّ بعدها، ولو زال تماماً. لا تنم عليه ولا تجرّب مسكّناً وتنتظر، ولا تقُد سيارتك. واطلبه كذلك إذا صحب الصداعَ المفاجئ قيءٌ أو تيبّس رقبة أو نفور شديد من الضوء أو تشوّش في الوعي أو تشنّج أو ضعف في طرف أو ازدواج رؤية أو تدلّي جفن. واذهب للطوارئ إذا بدأ الصداع أثناء مجهود أو جماع أو رفع ثقيل، أو إذا كان أول صداع من نوعه بعد سنّ الأربعين، أو كان أشدّ صداع عرفته وأنت تعرف صداعك. وراجع طبيب أعصاب في موعد قريب إذا كان في أقاربك من الدرجة الأولى إصابتان بتمدّد أوعية دماغية، فقد يُنصح بمسح وقائي.',
    en: 'Call an ambulance at once — this is not a clinic matter and not one to wait on — if a headache reaches its peak in under a minute, even if it then eases, even if it clears entirely. Do not sleep on it, do not try a painkiller and wait, and do not drive. Call too if the sudden headache comes with vomiting, a stiff neck, strong dislike of light, clouded consciousness, a seizure, limb weakness, double vision or a drooping eyelid. Go to emergency if the headache began during exertion, intercourse or lifting, if it is the first of its kind after forty, or if it is the worst you have known and you know your own headaches. See a neurologist soon if two first-degree relatives have had brain aneurysms, as screening may be advised.'
  },
  updated: '2026-09-08'
};

DX_BODY['guillain-barre'] = {
  symptoms: {
    ar: 'تبدأ القصّة غالباً بعد أسبوع إلى ثلاثة من نزلة معوية أو تنفّسية عابرة. أول ما يُحسّ خدر ووخز في أصابع القدمين واليدين، ثم يظهر ضعف في الساقين: صعود الدرج يثقل، والوقوف من الكرسي يحتاج دفعاً باليدين، والمشية تتمايل. والمميّز أن الضعف يصعد: من القدمين إلى الفخذين إلى الجذع إلى اليدين، ويتقدّم يوماً بعد يوم لا ساعةً بعد ساعة، وهو متناظر في الجهتين غالباً. ومع تقدّمه قد يصيب عضلات الوجه فيصعب الإغلاق التامّ للعين والابتسام، وعضلات البلع فيشرق الماء ويتغيّر الصوت. ويصحبه ألم عميق في الظهر والفخذين يُخطئ الناس فهمه. والعلامة الأخطر ضيق النفس أو ضحالة التنفّس أو صعوبة إكمال الجملة في نفَس واحد.',
    en: 'The story usually begins one to three weeks after a passing gut or chest infection. The first feeling is numbness and pins and needles in the toes and fingers, then weakness appears in the legs: stairs grow heavy, rising from a chair needs a push of the hands, and the walk sways. What marks it is that the weakness climbs: from the feet to the thighs, the trunk, the hands, advancing day by day rather than hour by hour, and usually symmetrical on both sides. As it advances it may reach the facial muscles so closing the eye and smiling become hard, and the swallowing muscles so water goes down the wrong way and the voice changes. Deep pain in the back and thighs accompanies it. The gravest sign is breathlessness or shallow breathing.'
  },
  cause: {
    ar: 'هو خطأ من جهاز المناعة لا عدوى في الأعصاب نفسها. حين يقاوم الجسم جرثومة معيّنة يصنع أجساماً مضادة تلتصق بسطحها، ويصادف أن أجزاءً من غلاف العصب المحيطي تشبه ذلك السطح، فتهاجمها الأجسام المضادة بالخطأ وتُتلف الغلاف الميليني الذي يعزل العصب ويسرّع نقل الإشارة، أو تُتلف محور العصب نفسه في الصور الأشدّ. فتضعف الإشارة أو تنقطع بين النخاع والعضلة. وأشيع ما يسبقها التهاب معوي بجرثومة تنتقل بالدجاج غير مطهوّ جيداً، وبعض الفيروسات التنفّسية وفيروسات أخرى، وقد تلي أحياناً تطعيماً أو عملية جراحية. وليست وراثية ولا معدية، ولا ذنب للمصاب فيها، وأكثر المصابين يتحسّنون حين تتوقّف الموجة المناعية ويُعاد بناء الغلاف.',
    en: 'It is an error of the immune system, not an infection of the nerves themselves. While fighting a particular germ the body makes antibodies that stick to its surface, and parts of the covering of the peripheral nerve happen to resemble that surface, so the antibodies attack them by mistake and damage the myelin sheath that insulates the nerve and speeds its signal, or in severer forms the nerve fibre itself. The signal between cord and muscle weakens or is cut. What most often precedes it is a gut infection from a germ carried on undercooked chicken, some respiratory and other viruses, and occasionally it follows a vaccination or an operation. It is neither inherited nor contagious, and most people improve as the immune wave stops and the sheath is rebuilt.'
  },
  diagnosis: {
    ar: 'التشخيص سريري في أساسه: ضعف صاعد متناظر يتقدّم بالأيام مع اختفاء المنعكسات الوترية عند الطرق على الركبة والكاحل، وهي علامة مبكّرة مهمّة. ويُدعم بثلاثة فحوص. الأول تخطيط الأعصاب والعضلات بالكهرباء، ويُظهر بطء نقل الإشارة أو تعطّلها ويفرّق بين الصورة الميلينية والمحورية. والثاني بزل قطني يُظهر ارتفاع البروتين في السائل الشوكي مع بقاء كريات الدم البيضاء طبيعية، وهذا التفارق مميّز، وقد لا يظهر في الأيام الأولى فيُعاد. والثالث ــ وهو الأهمّ عملياً ــ قياس سعة التنفّس عند السرير بشكل متكرّر، لأنه ينذر بالحاجة إلى جهاز تنفّس قبل أن يختنق المريض. وتُطلب تحاليل دم لاستبعاد أسباب أخرى للضعف، ويُراقب القلب والضغط لأن الأعصاب الذاتية قد تتأثّر.',
    en: 'The diagnosis is essentially clinical: symmetrical ascending weakness advancing over days with loss of the tendon reflexes at the knee and ankle, an important early sign. Three tests support it. First, electrical nerve and muscle studies, showing slowed or blocked conduction and separating the myelin form from the fibre form. Second, a lumbar puncture showing raised protein in the spinal fluid while the white cells stay normal, a distinctive dissociation that may be absent in the first days and is repeated. Third, and practically the most important, repeated bedside measurement of breathing capacity, since it warns of the need for a ventilator before the patient suffocates. Blood tests exclude other causes of weakness, and heart and blood pressure are monitored as the autonomic nerves may be affected.'
  },
  treatment: {
    ar: 'الدخول إلى المستشفى ليس احتياطاً زائداً بل هو العلاج نفسه، لأن الخطر الأكبر هو ضعف عضلات التنفّس والبلع، وهو يتقدّم بصمت ويُكشف بالقياس المتكرّر لا بالإحساس. ولذلك يُراقب التنفّس والقلب والضغط عن قرب، ويُنقل المريض إلى العناية المركّزة إن هبط تنفّسه، وقد يُوصل بجهاز تنفّس مؤقّتاً حتى تمرّ الموجة. أما العلاج الموجّه فأحد خيارين متكافئين يقرّرهما الفريق: تسريب أجسام مناعية وريدياً، أو تبديل البلازما الذي يسحب الأجسام المضادة من الدم، وكلاهما أنفع كلّما بُدئ مبكراً. ولا يُستعمل الكورتيزون وحده هنا. ويُضاف علاج للألم العصبي، ووقاية من الجلطات الوريدية بدواء مانع للتخثّر مع الجوارب الضاغطة لمن لا يقدر على المشي، وعلاج طبيعي مبكّر لمنع تيبّس المفاصل، ثم تأهيل طويل قد يمتدّ شهوراً.',
    en: 'Admission to hospital is not excess caution but the treatment itself, because the greatest danger is weakness of the breathing and swallowing muscles, which advances silently and is detected by repeated measurement rather than by feeling. Breathing, heart and blood pressure are therefore watched closely, the patient is moved to intensive care if breathing falls, and may be placed on a ventilator temporarily until the wave passes. The directed treatment is one of two equivalent options decided by the team: an intravenous infusion of immune antibodies, or plasma exchange which removes the offending antibodies from the blood; both work better the earlier they begin. Steroids alone are not used here. Nerve-pain relief, clot prevention with an anticoagulant medicine alongside compression stockings for anyone who cannot walk and early physiotherapy are added, then long rehabilitation.'
  },
  seeDoctor: {
    ar: 'اذهب للطوارئ في اليوم نفسه — لا موعد ولا انتظار — إذا ظهر ضعف في الساقين يتقدّم خلال ساعات أو أيام، أو صعُد خدر من القدمين نحو الأعلى، أو صرت تتعثّر وتسقط أو لا تستطيع الوقوف من الكرسي بلا يديك، وخصوصاً إن سبق ذلك إسهال أو نزلة قبل أسبوعين. واطلب الإسعاف فوراً إذا صحب الضعفَ ضيقُ نفس أو نفَس قصير لا يكمل الجملة، أو شرقة بالماء أو صعوبة بلع أو تغيّر صوت، أو ضعف في الوجه، أو خفقان شديد وتقلّب في الضغط. والقاعدة هنا أن سرعة التقدّم هي الخطر: ضعف يزداد يوماً بعد يوم يعني المستشفى اليوم لا غداً، حتى وإن كان المشي ما زال ممكناً.',
    en: 'Go to emergency the same day — no appointment and no waiting — if weakness appears in the legs and advances over hours or days, if numbness climbs from the feet upward, or if you begin to trip and fall or cannot rise from a chair without your hands, especially if diarrhoea or an illness preceded it by two weeks. Call an ambulance at once if the weakness comes with breathlessness or a breath too short to finish a sentence, choking on water, difficulty swallowing, a changed voice, facial weakness, or violent palpitations and swinging blood pressure. The rule here is that speed of progression is the danger: weakness increasing day by day means hospital today, not tomorrow, even if walking is still possible.'
  },
  updated: '2026-09-08'
};

DX_BODY['subdural-hematoma'] = {
  symptoms: {
    ar: 'له صورتان مختلفتان تماماً. الحادّة تلي إصابة رأس قوية فتظهر خلال ساعات: صداع يشتدّ، وقيء، وتخليط، ونعاس يتعمّق حتى لا يستيقظ المصاب، وقد يضعف نصف الجسم أو تتّسع حدقة عين واحدة. أما الصورة المزمنة فهي الأخطر لأنها تُخطئ كثيراً: تصيب كبير السن بعد ضربة رأس بسيطة قد لا يذكرها أصلاً، ولا يظهر شيء لأسابيع، ثم يتغيّر الرجل تدريجياً — صداع مستمرّ ممل، ونعاس وبطء تفكير، ونسيان جديد، وتغيّر مزاج، ومشية متمايلة أو سقوط متكرّر، وضعف خفيف في يد أو ساق من جهة واحدة، وقد يتلعثم كلامه. فيُقال إنه شاخ أو أصابه خرف، والحقيقة تجمّع دم يضغط دماغه ويمكن تفريغه.',
    en: 'It has two quite different faces. The acute one follows a strong head injury and appears within hours: worsening headache, vomiting, confusion and deepening drowsiness until the person cannot be roused, sometimes with weakness of one side or a widening pupil in one eye. The chronic face is the more dangerous because it is so often missed: it strikes an older person after a minor knock they may not even recall, nothing shows for weeks, then the person changes gradually — a dull persistent headache, drowsiness and slowed thinking, new forgetfulness, a change of mood, an unsteady walk or repeated falls, slight weakness of a hand or leg on one side, and sometimes slurred speech. It is called ageing or dementia, while in truth a collection of blood presses the brain and can be drained.'
  },
  cause: {
    ar: 'بين الدماغ وغلافه الخارجي تعبر أوردة صغيرة تُسمّى الأوردة الجسرية. ومع التقدّم في العمر يضمر الدماغ قليلاً فيتّسع الحيّز حوله وتصير هذه الأوردة مشدودة ومكشوفة، فتكفي حركة رأس عنيفة أو سقطة خفيفة أو ارتطام بباب خزانة لتمزّق واحداً منها. والنزف وريدي بطيء الضغط، فيتجمّع الدم على مهل ولا يظهر أثره إلا حين يكبر التجمّع ويبدأ بضغط الدماغ، ولهذا تطول الفترة بين الضربة والأعراض. وما يزيد الاحتمال: السنّ، وضمور الدماغ، ومميّعات الدم ومضادات الصفائح وهي عامل كبير جداً، وإدمان الكحول، والسقوط المتكرّر، والصرع، وغسيل الكلى، واضطرابات التخثّر. وعند الرضّع تُثير الحالةُ سؤالاً عن الهزّ العنيف.',
    en: 'Small bridging veins cross between the brain and its outer covering. With age the brain shrinks a little, the space around it widens and these veins are stretched and exposed, so a violent head movement, a light fall or a knock against a cupboard door is enough to tear one. The bleeding is venous and low in pressure, so blood gathers slowly and shows no effect until the collection grows and begins to press the brain, which is why the gap between blow and symptoms is long. What raises the risk: age, brain shrinkage, blood thinners and antiplatelet drugs which weigh very heavily, alcohol dependence, repeated falls, epilepsy, dialysis and clotting disorders. In infants the condition raises a question about violent shaking.'
  },
  diagnosis: {
    ar: 'الفحص الفاصل هو الأشعة المقطعية للرأس بلا صبغة، وهي سريعة ومتاحة وتُظهر التجمّع الدموي كهلال يحاذي عظم الجمجمة ويمتدّ فوق سطح الدماغ. ولون التجمّع في الصورة يدلّ على عمره: الدم الحديث يظهر أبيض ساطعاً، ومع مرور الأسابيع يبهت حتى يقارب لون الدماغ نفسه، وهنا تصعب رؤيته فيُستعان بالرنين المغناطيسي الذي يكشف التجمّعات القديمة والصغيرة والثنائية الجانب. وتُقاس درجة إزاحة الدماغ عن خطّ المنتصف لأنها تقرّر مدى الاستعجال. وتُسحب تحاليل تخثّر الدم لأن أغلب المصابين على مميّعات ويجب معرفة حالة التخثّر قبل أي تدخّل. ويُبحث عن كسر في الجمجمة أو نزف آخر مصاحب، وتُراجَع الأدوية كلها مع الطبيب.',
    en: 'The decisive test is a non-contrast CT of the head, quick and available, showing the collection as a crescent lying against the skull bone and spreading over the brain surface. Its colour on the image tells its age: fresh blood appears bright white, and over weeks it fades until it nearly matches the brain itself, at which point it is hard to see and MRI is used, which reveals old, small and two-sided collections. The shift of the brain away from the midline is measured, since it decides how urgent matters are. Clotting tests are drawn because most patients are on thinners and their clotting state must be known before any intervention. A skull fracture or other accompanying bleed is sought, and all medicines reviewed with the doctor.'
  },
  treatment: {
    ar: 'القرار يتبع حجم التجمّع وأثره لا وجوده وحده. فالتجمّع الصغير عند مريض واعٍ بلا علامات عصبية قد يُتابَع بالمراقبة وتصوير مُعاد، مع مراجعة عاجلة لمميّعات الدم ومضادات الصفائح وقرار بإيقافها أو عكس مفعولها يتّخذه الطبيب لا المريض. أما التجمّع الكبير أو الذي يضغط الدماغ أو يسبّب تدهوراً في الوعي فيحتاج تفريغاً جراحياً، وهو عند كبار السن في الحالة المزمنة غالباً إجراء محدود: ثقب أو ثقبان في الجمجمة يُصرَّف منهما الدم المتميّع، والنتائج بعده جيدة عادةً ويتحسّن الإدراك والمشية بسرعة تفاجئ الأهل. وفي الحالة الحادّة الشديدة قد يلزم فتح أوسع. وبعدها متابعة بالتصوير لأن التجمّع قد يعود، ووقاية من السقوط في البيت، وقرار محسوب بشأن استئناف المميّعات.',
    en: 'The decision follows the collection\'s size and effect, not its mere presence. A small collection in an alert patient with no neurological signs may be watched with repeat imaging, alongside an urgent review of blood thinners and antiplatelet drugs and a decision to stop or reverse them taken by the doctor, not the patient. A large collection, or one pressing the brain or causing declining consciousness, needs surgical drainage, which in the chronic elderly case is usually a limited procedure: one or two holes in the skull through which the liquefied blood is drained, with generally good results and a recovery of thinking and walking that surprises the family. A severe acute case may need a wider opening. Repeat imaging follows, with fall-proofing at home and a measured decision about restarting thinners.'
  },
  seeDoctor: {
    ar: 'اطلب الإسعاف فوراً بعد أي ضربة رأس إذا تبع الضربةَ قيءٌ ولو مرّة واحدة أو نعاس لا يُقاوم أو صعوبة في الإيقاظ أو تشوّش أو تشنّج أو ضعف في طرف أو تلعثم أو ازدواج رؤية أو تفاوت في اتّساع الحدقتين أو خروج دم أو سائل صافٍ من الأنف أو الأذن، أو فقد الوعي بعد الضربة، أو كانت الضربة قوية كسقوط من ارتفاع أكثر من متر أو حادث سيارة — وهذا وحده يستدعي الإسعاف ولو بدا المصاب بخير بعده. واذهب للطوارئ في اليوم نفسه بعد أي ضربة رأس ولو بدت بسيطة إذا كنت تستعمل مميّعاً للدم أو مضاداً للصفائح، أو عندك اضطراب في تخثّر الدم كالهيموفيليا، أو سبقت لك جراحة في الدماغ، أو كنت فوق الخامسة والستين، أو تشرب كحولاً بكثرة — فهذه المجموعات تنزف بعد ضربة لا تؤذي غيرها. واحجز موعداً قريباً إذا تغيّر كبير السنّ في البيت خلال أسابيع: صداع مستمرّ، نسيان جديد، بطء، تغيّر شخصية، سقوط متكرّر أو تمايل — واذكر للطبيب أي ارتطام رأس ولو قديماً وبسيطاً.',
    en: 'Call an ambulance at once after any blow to the head if it is followed by vomiting even once, irresistible drowsiness or difficulty waking, confusion, a seizure, limb weakness, slurred speech, double vision, unequal pupils, or blood or clear fluid from the nose or ear, or if consciousness was lost after the blow, or if the impact was heavy — a fall from more than a metre, or a car crash — which on its own warrants an ambulance even if the person seems well afterwards. Go to emergency the same day after any head knock, however slight, if you take a blood thinner or an antiplatelet drug, have a clotting disorder such as haemophilia, have had brain surgery before, are over sixty-five, or drink heavily — these groups bleed after a blow that would not harm others. Book an early appointment if an older person at home changes over weeks: persistent headache, new forgetfulness, slowness, a change of personality, repeated falls or unsteadiness — and tell the doctor of any head knock, even an old and trivial one.'
  },
  updated: '2026-09-08'
};

/* ==================== أمراض العصبون والحركة ==================== */

DX_BODY['als'] = {
  symptoms: {
    ar: 'يبدأ في مكان واحد صغير ثم ينتشر منه. عند أكثر الناس يبدأ في طرف: يد تضعف قبضتها فتسقط منها الأشياء ويصعب تدوير المفتاح أو تزرير القميص، أو قدم تتدلّى فتتعثّر في السجّاد وتُصدر صفعاً عند المشي. وعند آخرين يبدأ في الكلام والبلع: نطق يثقل ويصير غير واضح للمستمع، وشرقة بالماء، وسيلان لعاب. ومن علاماته المميّزة رجفان دقيق تحت الجلد يُرى كأن العضلة تنبض من نفسها، وتشنّجات مؤلمة، ونحول واضح في العضلة نفسها حتى يبين شكل اليد. ومع الوقت تضعف عضلات التنفّس فيظهر ضيق نفس عند الاستلقاء ونوم متقطّع وصداع صباحي. والإحساس والبصر والسمع والذاكرة الأساسية تبقى سليمة عند أكثر المصابين، فيعي الإنسان كل ما يجري له.',
    en: 'It begins in one small place and spreads from it. In most people it starts in a limb: a hand whose grip weakens so objects drop and turning a key or fastening a button becomes hard, or a foot that drops so it catches on the carpet and slaps the ground. In others it starts in speech and swallowing: speech grows heavy and unclear to the listener, water goes down the wrong way, saliva escapes. A distinctive sign is fine rippling under the skin as though the muscle were pulsing by itself, with painful cramps and visible wasting until the shape of the hand shows. In time the breathing muscles weaken, giving breathlessness on lying flat, broken sleep and morning headache. Sensation, sight, hearing and basic memory stay intact in most, so the person is aware of everything.'
  },
  cause: {
    ar: 'المرض يصيب العصبونات الحركية وحدها: تلك التي تنطلق من قشرة الدماغ نحو النخاع الشوكي، وتلك التي تخرج من النخاع إلى العضلة. وحين تموت هذه الخلايا تفقد العضلة أمرها فتضمر، وتظهر في الوقت نفسه علامات التصلّب من فقد العصبون الأعلى: تيبّس وزيادة في المنعكسات. والسبب الدقيق لموتها غير معروف بعد، ويُرجَّح أنه اجتماع عدّة عوامل: تراكم بروتينات مشوّهة داخل الخلية، وخلل في التخلّص من الفضلات، وإجهاد تأكسدي، وسمّية من فرط التنبيه. وفي حدود واحد من كل عشرة تقريباً يكون وراثياً بطفرة تسري في العائلة، والبقية تظهر بلا تاريخ عائلي. ويصيب الرجال أكثر قليلاً، وأغلب الحالات بعد منتصف العمر. وليس معدياً ولا ينتقل بالمخالطة.',
    en: 'The disease strikes the motor neurones alone: those running from the brain cortex toward the spinal cord, and those leaving the cord for the muscle. When these cells die the muscle loses its command and wastes, while signs of stiffness from loss of the upper neurone appear at the same time: rigidity and brisk reflexes. The exact reason for their death is still unknown, and several factors are thought to combine: misfolded proteins accumulating inside the cell, faulty clearance of waste, oxidative stress and over-excitation toxicity. In roughly one in ten it is inherited through a mutation running in the family, while the rest arise with no family history. It affects men slightly more, mostly after middle age, and it is not contagious.'
  },
  diagnosis: {
    ar: 'لا يوجد تحليل واحد يقول هذا هو المرض، فالتشخيص يُبنى على اجتماع علامات فقد العصبون الأعلى والأدنى في مناطق متعدّدة من الجسم مع استبعاد كل ما يشبهه. ولذلك يُحال المريض إلى طبيب أعصاب، ويُجرى تخطيط كهربائي للعضلات والأعصاب، وهو الفحص الأهمّ لأنه يكشف تلف العصبون الحركي حتى في عضلات تبدو سليمة، ويستبعد اعتلال الأعصاب المحيطية وأمراض الوصل العصبي العضلي. ويُصوَّر الدماغ والنخاع الرقبي بالرنين المغناطيسي لاستبعاد انضغاط النخاع في الرقبة، وهو سبب يشبهه كثيراً وقابل للجراحة. وتُسحب تحاليل دم واسعة تشمل الدرقية وفيتامين ب١٢ وعلامات المناعة وأحياناً فحوصاً وراثية. وقد يحتاج الأمر إعادة التقييم بعد أشهر لأن الصورة تتوضّح مع الوقت.',
    en: 'No single test declares the disease; the diagnosis is built on finding signs of upper and lower motor neurone loss in several regions of the body while excluding everything that resembles it. The patient is therefore referred to a neurologist, and electrical studies of muscles and nerves are done, the most important test, since it reveals motor neurone damage even in muscles that look normal and excludes peripheral neuropathies and disorders of the nerve-muscle junction. Brain and cervical cord are imaged by MRI to exclude cord compression in the neck, a close mimic that surgery can treat. Wide blood tests are drawn including thyroid, vitamin B12, immune markers and sometimes genetic studies. Reassessment after months may be needed as the picture clarifies.'
  },
  treatment: {
    ar: 'لا يوجد حتى الآن علاج يوقف المرض أو يعكسه، لكن هذا لا يعني أن لا شيء يُفعل — بل إن الرعاية المنظّمة تصنع فرقاً حقيقياً في الطول وفي جودة الأيام معاً. وأفضل ما يُفعل هو المتابعة في عيادة متعدّدة التخصّصات يجتمع فيها طبيب الأعصاب وأخصائي التنفّس والعلاج الطبيعي والوظيفي وأخصائي النطق والبلع والتغذية والدعم النفسي. وهناك أدوية موجّهة تُبطئ التقدّم قليلاً يقرّرها الطبيب. وأكبر أثر مثبَت هو دعم التنفّس بجهاز تهوية غير باضع يُلبس ليلاً حين يبدأ التنفّس بالضعف، فهو يحسّن النوم والطاقة ويطيل العمر. ويُعتنى بالتغذية مبكراً، وقد يُنصح بأنبوب تغذية عند صعوبة البلع قبل أن يهبط الوزن. ويُعالَج اللعاب والتشنّج والألم، وتُوفَّر وسائل تواصل بديلة، ويُخطَّط مبكراً لما يريده المريض نفسه.',
    en: 'There is as yet no treatment that stops or reverses the disease, but this does not mean nothing can be done — organised care makes a real difference to both length and quality of days. The best step is follow-up in a multidisciplinary clinic bringing together the neurologist, a respiratory specialist, physiotherapy and occupational therapy, speech and swallowing therapy, nutrition and psychological support. Targeted medicines that slow progression a little are decided by the doctor. The largest proven benefit is breathing support with a non-invasive ventilator worn at night once breathing begins to weaken, improving sleep, energy and survival. Nutrition is attended to early, and a feeding tube may be advised before weight falls. Saliva, spasticity and pain are treated, alternative means of communication provided, and the person\'s own wishes planned for early.'
  },
  seeDoctor: {
    ar: 'اطلب الإسعاف فوراً إذا ظهر ضيق نفس شديد أو لهاث في الراحة أو ازرقاق الشفاه، أو اختنق المريض بطعام أو ماء ولم يتحسّن، أو ظهرت حمّى وسعال منتج بعد شرقة متكرّرة فقد يكون التهاباً رئوياً استنشاقياً. واذهب في اليوم نفسه إذا هبط التنفّس بسرعة أو صار النوم متقطّعاً مع صداع عند الاستيقاظ. واحجز موعداً عند طبيب أعصاب دون تأخير — لا تنتظر أشهراً — إذا لاحظت ضعفاً ثابتاً يتقدّم في يد أو قدم بلا ألم، أو نحولاً في عضلة، أو رجفاناً دائماً تحت الجلد مع ضعف، أو تغيّراً في وضوح الكلام، أو شرقة متكرّرة بالسوائل. وطمأنة مهمّة: رجفان العضلات وحده بلا ضعف ولا نحول شائع جداً عند الأصحّاء ويرتبط بالتعب والقلق والكافيين، وقلّما يكون هذا المرض.',
    en: 'Call an ambulance at once if severe breathlessness appears, or panting at rest, or blue lips, or if the person chokes on food or water and does not recover, or if fever and a productive cough follow repeated choking, since this may be aspiration pneumonia. Go the same day if breathing falls quickly or sleep becomes broken with headache on waking. Book an appointment with a neurologist without delay — do not wait months — if you notice steady progressive weakness in a hand or foot without pain, wasting of a muscle, constant rippling under the skin together with weakness, a change in clarity of speech, or repeated choking on liquids. An important reassurance: muscle twitching alone, without weakness or wasting, is very common in healthy people and linked to fatigue, anxiety and caffeine.'
  },
  updated: '2026-09-08'
};

DX_BODY['essential-tremor'] = {
  symptoms: {
    ar: 'الرجفة هنا رجفة فعل لا رجفة سكون: تظهر حين تستعمل يدك وتختفي حين تتركها في حجرك. فيرتجف الكوب عند رفعه حتى ينسكب الشاي، ويتعرّج الخطّ عند الكتابة وتصغر الأسطر، ويصعب حمل الملعقة إلى الفم وسكب الماء في كوب ضيّق، وتضطرب اليد أكثر كلّما قاربت الهدف. وتصيب اليدين غالباً في الجهتين، وقد تمتدّ إلى الرأس فيهزّ الإنسان رأسه هزّاً خفيفاً بلا قصد، أو إلى الصوت فيصير مرتجفاً كأنه متأثّر. وتزيد مع التوتّر والإرهاق والجوع والكافيين والنظر إليها، وتخفّ عند كثيرين بشرب قليل من الكحول ثم تعود أشدّ. وتتقدّم ببطء شديد على مدى سنوات، ولا يصحبها بطء حركة ولا تيبّس ولا اختلال مشية.',
    en: 'The tremor here is one of action, not of rest: it appears when you use your hand and vanishes when it lies in your lap. The cup shakes as it is lifted until the tea spills, writing wanders and the lines shrink, carrying a spoon to the mouth or pouring water into a narrow glass grows hard, and the hand grows more unsteady the nearer it comes to its target. It usually affects both hands, and may reach the head so it nods slightly without intent, or the voice so it sounds quavering as if moved. It increases with tension, exhaustion, hunger, caffeine and being watched, and eases in many with a little alcohol before returning worse. It advances very slowly over years, without slowness of movement, rigidity or disturbed walking.'
  },
  cause: {
    ar: 'ليس تلفاً في الدماغ ولا موتاً للخلايا، وإنما خلل في ضبط الإيقاع داخل دائرة تصل المخيخ بجذع الدماغ بالمهاد والقشرة الحركية، فتصدر عنها إشارات إيقاعية تصل العضلة فترتجف اليد أثناء الفعل. وهو أشيع اضطرابات الحركة على الإطلاق، ويسري في العائلات بوضوح: كثير من المصابين لهم أب أو أمّ أو أخ مصاب، وقد يبدأ في الشباب ويبقى خفيفاً سنوات طويلة، ويزداد وضوحاً بعد الخمسين. وليس كل رجفة رجفة أساسية، فهناك ما يقلّدها ويجب استبعاده: فرط نشاط الغدة الدرقية، وانخفاض السكر، وفرط الكافيين، وأدوية عديدة تسبّب رجفة معروفة عند الطبيب، وسحب الكحول، والقلق الشديد، ومرض باركنسون الذي ترتجف فيه اليد وهي ساكنة لا وهي تعمل.',
    en: 'It is not brain damage nor the death of cells, but a fault in rhythm control within a circuit joining the cerebellum, brainstem, thalamus and motor cortex, which sends rhythmic signals to the muscle so the hand shakes during action. It is by far the commonest movement disorder and clearly runs in families: many sufferers have an affected parent or sibling. It may begin in youth and stay mild for years, becoming clearer after fifty. Not every tremor is essential, and mimics must be excluded: an overactive thyroid, low blood sugar, excess caffeine, many medicines known to the doctor for causing tremor, alcohol withdrawal, severe anxiety, and Parkinson\'s disease, in which the hand shakes at rest rather than in action.'
  },
  diagnosis: {
    ar: 'التشخيص سريري ويعتمد على المشاهدة أكثر من الأجهزة. يطلب الطبيب من المريض أن يمدّ يديه ويثبّتهما، ثم أن يقرّب إصبعه إلى أنفه، ثم أن يرسم حلزوناً ويكتب جملة ويصبّ ماءً من كوب إلى كوب، ويقارن الرجفة في الحالات الثلاث: السكون والوضع الثابت والحركة الموجّهة. وهذا وحده يفصل غالباً بين الرجفة الأساسية وبين باركنسون، إذ تكون رجفة باركنسون أوضح ما تكون واليد ساكنة في الحجر ومعها بطء حركة وتيبّس وتناقص في تأرجح الذراع أثناء المشي. ثم تُسحب تحاليل لاستبعاد المقلّدات: وظائف الدرقية أوّلها، مع السكر وأملاح الدم وأحياناً النحاس عند الشباب. وتُراجَع قائمة الأدوية كاملةً مع الطبيب. ولا تُطلب أشعة للدماغ في الحالة النموذجية، بل حين تكون الرجفة في جهة واحدة أو تظهر معها علامات أخرى.',
    en: 'The diagnosis is clinical and rests on observation more than machines. The doctor asks the person to hold the hands out steady, then to bring a finger to the nose, then to draw a spiral, write a sentence and pour water from cup to cup, comparing the tremor in three states: rest, held posture and guided movement. This alone usually separates essential tremor from Parkinson\'s, whose tremor is clearest with the hand still in the lap and comes with slowness, rigidity and a reduced arm swing while walking. Blood tests then exclude the mimics: thyroid function first, with sugar, salts and sometimes copper in young people. The full list of medicines is reviewed. Brain imaging is not needed in a typical case, only when the tremor is one-sided or other signs appear.'
  },
  treatment: {
    ar: 'ليست كل رجفة تحتاج علاجاً: إن كانت خفيفة ولا تعيق العمل ولا تُحرج صاحبها فيكفي الاطمئنان وفهم طبيعتها. والعلاج يبدأ حين تعيق الأكل أو الكتابة أو العمل أو تُخجل في المجالس. وأول ما يُفعل تعديل ما يزيدها: تقليل الكافيين ومنبّهات أخرى، ونوم كافٍ، وتقليل التوتّر بتمارين تنفّس، ومراجعة الأدوية التي قد تكون سبباً. وتساعد حيَل عملية كثيراً: أدوات مائدة ثقيلة المقبض، وأكواب بغطاء وقشّة، وأقلام غليظة، وتثبيت المرفق على الطاولة أثناء الكتابة، وأوزان معصم خفيفة. ثم أدوية يصفها الطبيب من فئتين معروفتين تخفّض شدّة الرجفة عند كثير من الناس ولا تُلغيها. وفي الحالات الشديدة التي لا تستجيب توجد خيارات تدخّلية في مراكز متخصّصة، منها التحفيز العميق للدماغ والعلاج بالموجات فوق الصوتية المركّزة.',
    en: 'Not every tremor needs treatment: if it is mild, does not hinder work and does not embarrass its owner, reassurance and understanding suffice. Treatment begins when it hinders eating, writing or work or causes embarrassment in company. The first step is adjusting what worsens it: less caffeine and other stimulants, enough sleep, less tension through breathing exercises, and review of medicines that may be the cause. Practical tricks help greatly: heavy-handled cutlery, lidded cups with a straw, thick pens, resting the elbow on the table while writing, and light wrist weights. Medicines from two well-known families, prescribed by the doctor, reduce the tremor\'s severity in many people without abolishing it. For severe unresponsive cases, specialist centres offer deep brain stimulation and focused ultrasound.'
  },
  seeDoctor: {
    ar: 'احجز موعداً عند طبيب أعصاب — لا طوارئ — إذا بدأت الرجفة تعيق الأكل أو الكتابة أو العمل، أو ازدادت بسرعة خلال أسابيع بدل التقدّم البطيء المعتاد، أو ظهرت في جهة واحدة من الجسم دون الأخرى، أو صحبها بطء في الحركة أو تيبّس أو صغر الخطّ أو قلّة تأرجح الذراع أثناء المشي أو اختلال في التوازن، فهذي علامات تُوجّه إلى تشخيص آخر. وراجع في موعد قريب أيضاً إذا صحب الرجفةَ نقصُ وزن أو خفقان أو تعرّق أو حرارة وعدم تحمّل للحرّ فقد تكون الدرقية، أو إذا بدأت بعد دواء جديد. واذهب للطوارئ إذا جاءت الرجفة فجأة مع تلعثم أو ضعف في طرف أو ازدواج رؤية، أو مع تعرّق شديد وتخليط عند مريض سكري، أو مع حرارة وتخليط، فهذي حالات أخرى تماماً.',
    en: 'Book an appointment with a neurologist — not emergency — if the tremor begins to hinder eating, writing or work, if it worsens quickly over weeks instead of its usual slow course, if it appears on one side of the body only, or if it comes with slowness of movement, rigidity, shrinking handwriting, a reduced arm swing while walking or unsteadiness, as these point to another diagnosis. See a doctor soon too if the tremor comes with weight loss, palpitations, sweating, fever or intolerance of heat, which may be the thyroid, or if it began after a new medicine. Go to emergency if the tremor came on suddenly with slurred speech, limb weakness or double vision, or with heavy sweating and confusion in a diabetic, or with fever and confusion.'
  },
  updated: '2026-09-08'
};

DX_BODY['tourette'] = {
  symptoms: {
    ar: 'تبدأ في الطفولة غالباً بين الخامسة والسابعة بحركات صغيرة سريعة متكرّرة: رمش شديد، رفع الحاجب، هزّ الرأس، رفع الكتف، تكشير الوجه. ثم تنضمّ إليها أصوات: تنحنح متكرّر، شخير أنفي، شهقة، أو كلمة تُقال بلا مناسبة. والمفتاح لفهمها إحساس داخلي ملحّ يسبق الحركة كحكّة لا تُحتمل في مكان ما، ولا يهدأ إلا بأدائها، ثم يعود. ولذلك يستطيع الطفل كبحها لدقائق في الصفّ أو أمام الطبيب ثم تنفجر دفعة واحدة في البيت، فيُظنّ أنه يفعلها عمداً. وتزيد مع التعب والتوتّر والحماس وحتى مع الحديث عنها، وتخفّ مع الانشغال العميق بمهارة يحبّها، وتختفي غالباً في النوم. وتتقلّب أشكالها من شهر إلى شهر، وتشتدّ في المراهقة المبكّرة ثم تخفّ عند أكثرهم مع النضج.',
    en: 'It usually begins in childhood between five and seven with small, rapid, repeated movements: hard blinking, raising an eyebrow, shaking the head, shrugging a shoulder, grimacing. Sounds then join them: repeated throat-clearing, sniffing, a gasp, or a word said out of place. The key to understanding them is an insistent inner sensation preceding the movement, like an unbearable itch somewhere, which only performing it relieves, before it returns. So the child can hold them back for minutes in class or before the doctor, then they burst out at home, and it is thought deliberate. They increase with tiredness, tension, excitement and even talking about them, ease with deep absorption in a loved skill, and usually vanish in sleep. Their forms shift month to month, peak in early adolescence, then ease in most with maturity.'
  },
  cause: {
    ar: 'ليست نتيجة تربية ولا دلال ولا صدمة نفسية، ولا يستطيع الطفل إيقافها بالإرادة وإن بدا أنه يقدر. وأصلها اضطراب في دوائر عصبية تربط قشرة الدماغ بالنوى القاعدية العميقة التي تعمل كبوّابة تكبح الحركات غير المرغوبة قبل خروجها، فحين يضعف الكبح تخرج الحركة من تلقائها. وللوراثة دور واضح: كثيراً ما يوجد في العائلة عرّات أو وسواس قهري أو فرط حركة وتشتّت انتباه. وترافقها هذي الحالات كثيراً حتى إنها قد تكون أثقل على الطفل من العرّات نفسها: الوسواس القهري، وتشتّت الانتباه، والقلق، وصعوبات النوم والتعلّم. ولا يُظهر التصوير ولا التحاليل شيئاً، فالخلل وظيفي في الضبط لا بنيوي في التركيب. وأكثر الأطفال يخفّ عندهم الأمر كثيراً بعد المراهقة.',
    en: 'It is not the result of upbringing, indulgence or psychological trauma, and the child cannot stop it by will even though it seems he can. Its origin is a disturbance in circuits linking the brain cortex to the deep basal nuclei, which act as a gate holding back unwanted movements before they emerge; when that braking weakens, the movement escapes on its own. Heredity plays a clear part: tics, obsessive-compulsive disorder or attention deficit are often found in the family. These conditions frequently accompany it and may weigh on the child more than the tics themselves: obsessive-compulsive disorder, attention deficit, anxiety, and difficulties with sleep and learning. Imaging and tests show nothing, because the fault is functional in control rather than structural. In most children it eases greatly after adolescence.'
  },
  diagnosis: {
    ar: 'التشخيص سريري بالكامل، ولا يوجد تحليل ولا أشعة تثبته. يعتمد الطبيب على القصّة: متى بدأت، وهل هناك عرّات حركية وصوتية معاً، وهل استمرّت أكثر من سنة، وهل تتغيّر أشكالها وتتقلّب شدّتها، وهل يسبقها إحساس ملحّ ويمكن كبحها قليلاً. ويفيد كثيراً أن يصوّر الأهل مقطعاً قصيراً في البيت، لأن العرّات قد تختفي تماماً في العيادة. ويسأل الطبيب عن الوسواس والانتباه والقلق والنوم والأداء المدرسي والتنمّر، لأن علاج المرافق أهمّ من علاج العرّة أحياناً. ويستبعد ما يشبهها: تشنّجات لاإرادية من أدوية معيّنة، وحركات صرعية قصيرة، ونوبات الرمش من جفاف العين أو الحساسية، وحركات الكرع. وتُطلب تحاليل أو أشعة فقط إذا كانت الصورة غير نمطية أو ظهرت علامات عصبية أخرى.',
    en: 'The diagnosis is entirely clinical; no test or scan proves it. The doctor relies on the history: when it began, whether motor and vocal tics both exist, whether they have lasted more than a year, whether their forms change and their severity fluctuates, and whether an insistent urge precedes them and they can be briefly suppressed. A short video filmed by the family at home helps greatly, since tics may vanish entirely in clinic. The doctor asks about obsessions, attention, anxiety, sleep, school performance and bullying, because treating what accompanies matters more than treating the tic at times. Mimics are excluded: involuntary movements from certain medicines, brief seizure movements, blinking from dry eye or allergy, and chorea. Tests or imaging are requested only if the picture is atypical or other neurological signs appear.'
  },
  treatment: {
    ar: 'أول العلاج وأهمّه ليس دواءً بل تفسير: أن يفهم الأهل والمعلّمون أنها ليست عناداً، وأن يتوقّف تنبيه الطفل ولومه وطلب التوقّف منه لأن ذلك يزيدها. وكثير من الحالات الخفيفة لا تحتاج أكثر من ذلك مع تعديل بسيط في المدرسة: مقعد مناسب، وسماح بالخروج لحظة، ووقت إضافي في الامتحان، وحماية من التنمّر. وحين تكون العرّات مؤذية أو مؤلمة أو تعطّل التعلّم، فأول خيار مثبَت هو العلاج السلوكي الموجّه للعرّات، ويُعلَّم فيه الطفل أن ينتبه للإحساس السابق وأن يستبدل بالحركة استجابة منافسة غير ملحوظة، مع تدريب على الاسترخاء. ثم تأتي أدوية يقرّرها الطبيب النفسي أو العصبي وتُوازَن فوائدها بآثارها. ويُعالَج المرافق: الوسواس والقلق وتشتّت الانتباه ومشاكل النوم — وتحسّنها يخفّف العرّات نفسها.',
    en: 'The first and most important treatment is not a medicine but an explanation: that the family and teachers understand this is not defiance, and that pointing it out, blaming the child and asking him to stop should cease, because that increases it. Many mild cases need no more, with small adjustments at school: a suitable seat, permission to step out for a moment, extra time in exams, and protection from bullying. When tics are harmful, painful or disrupt learning, the first proven option is behavioural therapy aimed at tics, teaching the child to notice the preceding sensation and replace the movement with an unnoticeable competing response, along with relaxation training. Medicines decided by the psychiatrist or neurologist follow, their benefits weighed against their effects. Accompanying obsessions, anxiety, attention deficit and sleep problems are treated, and improving them eases the tics themselves.'
  },
  seeDoctor: {
    ar: 'احجز موعداً عند طبيب أطفال أو أعصاب أطفال — لا طوارئ — إذا استمرّت الحركات أو الأصوات اللاإرادية أكثر من بضعة أسابيع، أو صارت تؤذي الطفل كأن يهزّ رقبته بعنف أو يضرب نفسه، أو صارت مؤلمة، أو أثّرت في نومه أو دراسته أو جعلته هدفاً للسخرية. وراجع في موعد قريب أيضاً إذا ظهر معها وسواس قهري أو قلق شديد أو تشتّت انتباه أو تراجع مفاجئ في التحصيل، فهذي غالباً هي ما يحتاج علاجاً قبل العرّة. واذهب للطوارئ إذا كانت الحركة مصحوبة بغياب عن الوعي أو تحديق ثابت لا يستجيب للنداء أو تشنّج في الطرفين أو تبوّل لا إرادي، فهذي نوبة صرعية لا عرّة، أو إذا ظهرت الحركات فجأة بعد حرارة والتهاب حلق أو بعد دواء جديد.',
    en: 'Book an appointment with a paediatrician or paediatric neurologist — not emergency — if involuntary movements or sounds last more than a few weeks, if they begin to harm the child, such as violently jerking the neck or striking himself, if they become painful, or if they affect his sleep, schooling or make him a target of mockery. See a doctor soon too if obsessive-compulsive behaviour, severe anxiety, attention difficulty or a sudden drop in achievement appear with them, as these often need treatment before the tic. Go to emergency if the movement comes with loss of awareness, a fixed stare unresponsive to calling, convulsion of both limbs or wetting, since this is a seizure rather than a tic, or if the movements began suddenly after fever and a sore throat or after a new medicine.'
  },
  updated: '2026-09-08'
};

